    setViewportScale: (scale: number) => boolean
    subscribeViewportScale: (listener: () => void) => () => void
}

interface DiagramZoomSliderProps {
    diagramIdentity: 'Current' | 'New'
    store: DiagramZoomStore
}

const ZOOM_MARKS = DIAGRAM_ZOOM_VALUES.map((value) => ({ value }))

function percentageText(value: number) {
    return `${Math.round(value * 100)}%`
}

/** Floating direct-scale control shared by Current and New diagram viewports. */
export function DiagramZoomSlider({ diagramIdentity, store }: DiagramZoomSliderProps) {
    const scale = useSyncExternalStore(
        store.subscribeViewportScale,
        store.getViewportScaleSnapshot,
        store.getViewportScaleSnapshot,
    )
    const handleChange = useCallback((_event: Event | SyntheticEvent, value: number | number[]) => {
        if (typeof value !== 'number') throw new Error('Diagram zoom slider requires one numeric value')
        store.setViewportScale(value)
    }, [store])

    return (
        <Box
            sx={{
                bgcolor: 'background.paper',
                border: '1px solid',
                borderColor: 'divider',
                borderRadius: 1,
                bottom: 2,
                boxShadow: 8,
                left: 2,
                px: 2,
                position: 'absolute',
                width: 176,
                zIndex: 2,
            }}
        >
            <Slider
                aria-label={`${diagramIdentity} diagram zoom`}
                getAriaValueText={percentageText}
                marks={ZOOM_MARKS}
                max={MAXIMUM_DIAGRAM_ZOOM}
                min={MINIMUM_DIAGRAM_ZOOM}
                onChange={handleChange}
                step={null}
                value={scale}
                valueLabelDisplay="auto"
                valueLabelFormat={percentageText}
            />
        </Box>
    )
}

    return { ...current, children, diagrams }
}

/** Owns diagram records, navigation, popup state, JSON loading, and persistence for one project. */
export class DiagramViewService extends EventTarget {
    private binding: DiagramProjectBinding | null = null
    private readonly dependencies: DiagramViewDependencies
    private loadPromise: Promise<void> | null = null
    private navigationToken = 0
    private processedRunIds = new Set<string>()
    private readonly pendingCopyRecordsBySourceId = new Map<string, DiagramRecord>()
    private projectKey: string | null = null
    private snapshot = INITIAL_SNAPSHOT
    private sourceSnapshot: DiagramViewSourceSnapshot | null = null
    private unsubscribeRunEvents: (() => void) | null = null
    private viewportScale = DEFAULT_DIAGRAM_ZOOM

    constructor(dependencies: Partial<DiagramViewDependencies> = {}) {
        super()
        this.dependencies = { ...defaultDependencies(), ...dependencies }
    }

    getSnapshot = () => this.snapshot

    getSourceSnapshot = () => this.sourceSnapshot

    getViewportScaleSnapshot = () => this.viewportScale

    subscribe = (listener: () => void) => {
        this.addEventListener('changed', listener)

        return () => this.removeEventListener('changed', listener)
    }

    subscribeSource = (listener: () => void) => {
        this.addEventListener('sourceChanged', listener)

        return () => this.removeEventListener('sourceChanged', listener)
    }

    subscribeViewportScale = (listener: () => void) => {
        this.addEventListener(VIEWPORT_SCALE_CHANGED_EVENT, listener)

        return () => this.removeEventListener(VIEWPORT_SCALE_CHANGED_EVENT, listener)
    }

    bindProject(binding: DiagramProjectBinding) {
        const projectKey = `${binding.project.id}:${binding.project.branch}`
        if (projectKey !== this.projectKey) this.clear()
        this.binding = binding
        this.projectKey = projectKey
    }

    clear() {
        this.binding = null
        this.loadPromise = null
        this.navigationToken += 1
        this.processedRunIds.clear()
        this.pendingCopyRecordsBySourceId.clear()
        this.projectKey = null
        this.unsubscribeRunEvents?.()
        this.unsubscribeRunEvents = null
        this.publish(INITIAL_SNAPSHOT, null)
    }

    /** Loads the index on first activation; a failed load is retried by the next call. */
    }

    private requireBinding() {
        if (!this.binding) throw new Error('Diagram view is not bound to a project')

        return this.binding
    }

    private requireReady() {
        if (this.snapshot.status !== 'ready') throw new Error('Diagram view is not ready')
    }

    private publish(snapshot: DiagramViewSnapshot, sourceSnapshot: DiagramViewSourceSnapshot | null = this.sourceSnapshot) {
        const sourceChanged = sourceSnapshot !== this.sourceSnapshot
        const activeDiagramChanged = sourceSnapshot?.record.id !== this.sourceSnapshot?.record.id
        this.snapshot = snapshot
        this.sourceSnapshot = sourceSnapshot
        if (activeDiagramChanged) this.resetViewportScale()
        if (sourceChanged) this.dispatchEvent(new Event('sourceChanged'))
        this.dispatchEvent(new Event('changed'))
    }

    private resetViewportScale() {
        if (this.viewportScale === DEFAULT_DIAGRAM_ZOOM) return

        this.viewportScale = DEFAULT_DIAGRAM_ZOOM
        this.dispatchEvent(new Event(VIEWPORT_SCALE_CHANGED_EVENT))
    }
}

export const diagramViewService = register('diagramViewService', new DiagramViewService())

export const DEFAULT_DIAGRAM_ZOOM = 1
export const DIAGRAM_ZOOM_STEP = 0.25
export const MINIMUM_DIAGRAM_ZOOM = 0.1
export const MAXIMUM_DIAGRAM_ZOOM = 2.5

export const DIAGRAM_ZOOM_VALUES: readonly number[] = Object.freeze([
    MINIMUM_DIAGRAM_ZOOM,
    ...Array.from(
        { length: MAXIMUM_DIAGRAM_ZOOM / DIAGRAM_ZOOM_STEP },
        (_value, index) => (index + 1) * DIAGRAM_ZOOM_STEP,
    ),
])

/** Requires one scale exposed by diagram zoom controls. */
export function requireDiagramZoom(scale: number) {
    if (!DIAGRAM_ZOOM_VALUES.includes(scale)) throw new Error(`Unsupported diagram zoom scale: ${scale}`)

    return scale
}

